//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");

//#include("../js/controlResize.js"); // 화면 리사이징	


scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;
scwin.gIsurCd;
scwin.gActTpCd;
scwin.gSeq;
scwin.gActTpCd;
scwin.gApprovStatCd;
scwin.regMode; // 'REG', 'MOD'
scwin.gComAbbrv;
scwin.pageUrl;
scwin.pageTitle;
scwin.pageW;
scwin.pageH;
scwin.vScrenID = 'ULDSTF37700.xml';
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

//페이지 로딩 시 필요한 변수 초기화
scwin.fn_SetCode = function() {
    dts_EMP_NO.DataID = "/CodeAction.do?method=getEmpNoDepCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_EMP_NO.Reset();
    dts_DEP_CD.DataID = "/CodeAction.do?method=getDepUpCode&inputMessageId=CODE_EMPDEP_IN&For=R&DEP_CD=" + scwin.gDepCd;
    dts_DEP_CD.Reset();
    dts_reflect.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CONFRM_PROCS_CHK_ENFORCE_DD_OUT";
    dts_reflect.reset();
    dts_reflect.insertRow();

    //조회일자 오늘로 셋팅
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SchDate.setValue("");
    //edt_SchDate.Text = vCurDate;		

    //부서코드 로그인 사용자 부서로 셋팅
    $c.stf.setObjectValue(cmb_DEP_CD, js_dep_cd);
    if ($c.stf.getObjectValue(cmb_DEP_CD) == '') {
        cmb_DEP_CD.setSelectedIndex(0);
    }
    if (scwin.gDepCd == 'ZSYS') {
        $c.stf.showObj(btn_reflect, true);
    } else {
        $c.stf.showObj(btn_reflect, false);
    }
};
scwin.fn_Search = function() {
    var vISUR_CD = $c.stf.getObjectValue(txb_isur_cd);
    var vDEP_CD = $c.stf.getObjectValue(cmb_DEP_CD);
    var vEMP_NO = $c.stf.getObjectValue(cmb_EMP_NO);
    var vSTAT_CD = $c.stf.getObjectValue(cmb_stat_cd);
    var vENFORCE_DD = $c.stf.getObjectValue(edt_SchDate);
    if (scwin.gLdMktTp == '9') {
        scwin.gLdMktTp = '1';
    } else {
        scwin.gLdMktTp = scwin.gLdMktTp;
    }
    var url = "/ConfrmProcs.do?method=listDesignConfrmProcs";
    url += "&ISUR_CD=" + vISUR_CD;
    url += "&CPOC_APPROV_STAT_CD=" + $c.stf.trim(vSTAT_CD);
    url += "&LD_MKT_TP_CD=" + scwin.gLdMktTp;
    url += "&ENFORCE_DD=" + vENFORCE_DD;
    url += "&DEP_CD=" + vDEP_CD;
    url += "&EMP_NO=" + vEMP_NO;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid);
};



// 확인절차 대상법인 지정 처리 체크
scwin.fn_checkConfrmProcsStat = function(pIsurCd, pActTpCd) {
    var vCPOC_SEQ;
    var vCPOC_ACT_TP_CD;
    var vCPOC_ACT_TP_NM;
    var vCPOC_APPROV_STAT_CD;
    var vCPOC_APPROV_STAT_NM;
    var vCPOC_ENFORCE_DD;
    dts_check.DataID = encodeURI("/ConfrmProcs.do?method=checkConfrmProcsStat&outputMessageId=CONFRM_PROCS_CHK_STAT_OUT&ISUR_CD=" + pIsurCd);
    dts_check.Reset();
    vCPOC_SEQ = dts_check.getCellData(1, "CPOC_SEQ");
    vCPOC_ACT_TP_CD = dts_check.getCellData(1, "CPOC_ACT_TP_CD");
    vCPOC_ACT_TP_NM = dts_check.getCellData(1, "CPOC_ACT_TP_NM");
    vCPOC_APPROV_STAT_CD = dts_check.getCellData(1, "CPOC_APPROV_STAT_CD");
    vCPOC_APPROV_STAT_NM = dts_check.getCellData(1, "CPOC_APPROV_STAT_NM");
    vCPOC_ENFORCE_DD = dts_check.getCellData(1, "CPOC_ENFORCE_DD");

    // 신규 등록시
    if (vCPOC_SEQ == undefined) {
        // [지정] 선택시
        if (pActTpCd == "1") {
            return true;
        } else {
            $c.win.alert("확인절차 대상법인으로 지정된 상태가 아닙니다.");
            return false;
        }
    } else {
        // [지정] 선택시
        if (pActTpCd == "1") {
            // 가장 마지막 조치가 [지정] 이면
            if (vCPOC_ACT_TP_CD == "1") {
                // 가장 마지막 조치의 승인상태가  [승인] 이면
                if (vCPOC_APPROV_STAT_CD == "30") {
                    $c.win.alert("이미 확인절차 대상법인으로 지정된 상태입니다.");
                    return false;
                } else {
                    $c.win.alert("확인절차 대상법인 지정 조치의 승인상태가 [" + vCPOC_APPROV_STAT_NM + "] 입니다.");
                    return false;
                }
                // 가장 마지막 조치가 [지정사유변경] 이면	

            } else if (vCPOC_ACT_TP_CD == "2") {
                // 가장 마지막 조치의 승인상태가  [승인] 이면
                if (vCPOC_APPROV_STAT_CD == "30") {
                    $c.win.alert("이미 확인절차 대상법인으로 지정된 상태입니다.");
                    return false;
                } else {
                    $c.win.alert("확인절차 대상법인 지정사유변경 조치의 승인상태가 [" + vCPOC_APPROV_STAT_NM + "] 입니다.");
                    return false;
                }
            } else {
                // 가장 마지막 조치의 승인상태가  [승인] 이면
                if (vCPOC_APPROV_STAT_CD == "30") {
                    return true;
                } else {
                    //alert("지정해제 후 확인절차 대상법인으로 지정 할 수 있습니다.");
                    $c.win.alert("확인절차 대상법인 지정해제 조치의 승인상태가 [" + vCPOC_APPROV_STAT_NM + "] 입니다.");
                    return false;
                }
            }

            // [지정사유변경] 선택시

        } else if (pActTpCd == "2") {
            // 가장 마지막 조치가 [지정] 이면
            if (vCPOC_ACT_TP_CD == "1") {
                // 가장 마지막 조치의 승인상태가  [승인] 이면
                if (vCPOC_APPROV_STAT_CD == "30") {
                    return true;
                } else {
                    $c.win.alert("확인절차 대상법인 지정 조치의 승인상태가 [" + vCPOC_APPROV_STAT_NM + "] 입니다.");
                    return false;
                }
                // 가장 마지막 조치가 [지정사유변경] 이면		

            } else if (vCPOC_ACT_TP_CD == "2") {
                // 가장 마지막 조치의 승인상태가  [승인] 이면
                if (vCPOC_APPROV_STAT_CD == "30") {
                    return true;
                } else {
                    $c.win.alert("확인절차 대상법인 지정사유변경 조치의 승인상태가 [" + vCPOC_APPROV_STAT_NM + "] 입니다.");
                    return false;
                }
            } else {
                // 가장 마지막 조치의 승인상태가  [승인] 이면
                if (vCPOC_APPROV_STAT_CD == "30") {
                    $c.win.alert("지정사유변경을 처리 할 수 없습니다. 먼저 지정 후 지정사유를 변경하세요.");
                    return false;
                } else {
                    $c.win.alert("확인절차 대상법인 지정해제 조치의 승인상태가 [" + vCPOC_APPROV_STAT_NM + "] 입니다.");
                    return false;
                }
            }

            // [지정해제] 선택시

        } else if (pActTpCd == "3") {
            // 가장 마지막 조치가 [지정] 이면
            if (vCPOC_ACT_TP_CD == "1") {
                // 가장 마지막 조치의 승인상태가  [승인] 이면
                if (vCPOC_APPROV_STAT_CD == "30") {
                    return true;
                } else {
                    $c.win.alert("확인절차 대상법인 지정 조치의 승인상태가 [" + vCPOC_APPROV_STAT_NM + "]입니다.");
                    return false;
                }
                // 가장 마지막 조치가 [지정사유변경] 이면		

            } else if (vCPOC_ACT_TP_CD == "2") {
                // 가장 마지막 조치의 승인상태가  [승인] 이면
                if (vCPOC_APPROV_STAT_CD == "30") {
                    return true;
                } else {
                    $c.win.alert("확인절차 대상법인 지정사유변경 조치의 승인상태가 [" + vCPOC_APPROV_STAT_NM + "] 입니다.");
                    return false;
                }
            } else {
                // 가장 마지막 조치의 승인상태가  [승인] 이면
                if (vCPOC_APPROV_STAT_CD == "30") {
                    $c.win.alert("이미 지정해제 된 상태입니다.");
                    return false;
                } else {
                    $c.win.alert("확인절차 대상법인 지정해제 조치의 승인상태가 [" + vCPOC_APPROV_STAT_NM + "] 입니다.");
                    return false;
                }
            }
        }
    }
    return true;
};





//TBLD_ISU_INST에 EXMPT_OBJ_DISCLS_YN 수동 반영
scwin.fn_updateExmptObjDisclsYn = function() {
    var tmpStr;
    var vMethod;
    vMethod = "updateExmptObjDisclsYn";
    tmpStr = "반영 하시겠습니까?";
    var vAnswer = confirm(tmpStr);
    if (vAnswer == true) {
        trs_reflect.Action = "/ConfrmProcs.do?method=" + vMethod + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_reflect.KeyName = "toinb_dataid4";
        trs_reflect.KeyValue = "JSP(I:pInput1=dts_reflect)";
        trs_reflect.Post();
    }
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    }
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin('', grd_Grid);
};
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    scwin.gSeq = dts_List.getCellData(eval(row), "CPOC_SEQ");
    scwin.gIsurCd = dts_List.getCellData(eval(row), "ISUR_CD");
    scwin.gActTpCd = dts_List.getCellData(eval(row), "CPOC_ACT_TP_CD");
    scwin.gApprovStatCd = dts_List.getCellData(eval(row), "CPOC_APPROV_STAT_CD");
    if (scwin.gApprovStatCd == "10") {
        scwin.regMode = 'MOD'; //수정 및 검토모드

    } else if (scwin.gApprovStatCd == "20") {
        scwin.regMode = 'APP'; //승인모드

    } else {
        scwin.regMode = 'VIEW'; //승인완료모드

    }


    // 지정	
    if (scwin.gActTpCd == '1') {
        scwin.pageUrl = '/dsclmgt/ULDSTF37701.gfm';
        scwin.pageTitle = '지정';
        scwin.pageW = '660';
        scwin.pageH = '350';

        // 지정사유변경

    } else if (scwin.gActTpCd == '2') {
        scwin.pageUrl = '/dsclmgt/ULDSTF37702.gfm';
        scwin.pageTitle = '지정사유변경';
        scwin.pageW = '660';
        scwin.pageH = '480';
        // 지정해제

    } else if (scwin.gActTpCd == '3') {
        scwin.pageUrl = '/dsclmgt/ULDSTF37701.gfm';
        scwin.pageTitle = '지정해제';
        scwin.pageW = '660';
        scwin.pageH = '350';
    }
    if (colid == "CPOC_DESIGN_RSN_NM") {
        // 승인상태 클릭 시
        await $c.frame.CreateDialogFrame("wndDiscls", scwin.pageUrl, "확인절차 대상법인 " + scwin.pageTitle, 300, 220, scwin.pageW, scwin.pageH, "window");
    }
    if (colid == "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    }
};
scwin.cmb_DEP_CD_OnSelChange = function() {
    scwin.gDepCd = $c.stf.getObjectValue(cmb_DEP_CD); //;.ValueOfIndex("VALUE", cmb_DEP_CD.Index);

    dts_EMP_NO.UseFilter = true;
    dts_EMP_NO.Filter();
};
scwin.dts_EMP_NO_OnFilter = function(row) {
    if (scwin.gDepCd == "") {
        // 전체일 경우 모두 보여준다.
        return true;
    } else {
        if (dts_EMP_NO.getCellData(row, "dep_cd") == scwin.gDepCd ||
            dts_EMP_NO.getCellData(row, "dep_cd") == "") {
            return true;
        } else {
            return false;
        }
    }
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch(txb_isur_cd, txb_com_abbrv);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_SchDate);
};
scwin.btn_Search_onclick = function() {
    scwin.fn_Search();
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07, '');
    $c.data.downloadGridViewExcel(grd_Grid, "확인절차 대상법인 지정/지정해제", "", "8");
};
scwin.btn_New_onclick = async function() {
    scwin.regMode = "REG";
    if ($c.stf.getObjectValue(txb_isur_cd) == '' || $c.stf.getObjectValue(txb_com_abbrv) == '') {
        $c.win.alert("확인절차 대상법인을 선택해 주세요.");
        txb_isur_cd.focus();
        return true;
    }
    if ($c.stf.getObjectValue(cmb_ActTpCd) == '') {
        $c.win.alert("조치구분을 선택해 주세요.");
        cmb_ActTpCd.focus();
        return true;
    }
    scwin.gIsurCd = $c.stf.getObjectValue(txb_isur_cd);
    scwin.gComAbbrv = $c.stf.getObjectValue(txb_com_abbrv);
    scwin.gActTpCd = $c.stf.getObjectValue(cmb_ActTpCd);

    // 지정	
    if ($c.stf.getObjectValue(cmb_ActTpCd) == '1') {
        scwin.pageUrl = '/dsclmgt/ULDSTF37701.gfm';
        scwin.pageTitle = '지정';
        scwin.pageW = '660';
        scwin.pageH = '350';

        // 지정사유변경

    } else if ($c.stf.getObjectValue(cmb_ActTpCd) == '2') {
        scwin.pageUrl = '/dsclmgt/ULDSTF37702.gfm';
        scwin.pageTitle = '지정사유변경';
        scwin.pageW = '660';
        scwin.pageH = '480';
        // 지정해제

    } else if ($c.stf.getObjectValue(cmb_ActTpCd) == '3') {
        scwin.pageUrl = '/dsclmgt/ULDSTF37701.gfm';
        scwin.pageTitle = '지정해제';
        scwin.pageW = '660';
        scwin.pageH = '350';
    }

    //확인절차 대상법인 지정 처리 체크	
    if (scwin.fn_checkConfrmProcsStat(scwin.gIsurCd, scwin.gActTpCd) == false) {
        cmb_ActTpCd.focus();
        return;
    }
    scwin.fn_Search();
    await $c.frame.CreateDialogFrame("wndDiscls", scwin.pageUrl, "확인절차 대상법인 " + scwin.pageTitle, 300, 220, scwin.pageW, scwin.pageH, "window");
};
scwin.trs_check_OnSuccess = async function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
    parent_function_call();
    await $c.frame.CloseFrame();
};
scwin.trs_check_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "등록"));
    $c.win.alert(trs_insert.ErrorMsg);
};
scwin.btn_reflect_onclick = function() {
    scwin.fn_updateExmptObjDisclsYn();
};
scwin.trs_reflect_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "등록"));
};
scwin.trs_reflect_OnFail = function() {
    //alert( getMessageParam("MSG-A002", "등록") );
    $c.win.alert(trs_reflect.ErrorMsg);
};
scwin.dts_reflect_OnLoadCompleted = function(rowcount) {

};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();

    //회사정보 로딩
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.fn_Search();
};
